import type { AdminBridge } from "@platform/admin-sdk";
import type {
  BundleId,
  BundleType,
  DiscountKind,
  BundleListItem,
  BundleRow,
  BundleMemberRow,
  BundleDiscountTierRow,
  MemberInput,
  TierInput,
  AdminListBundlesResponse,
  AdminBundleDetailResponse,
  AdminCreateBundleResponse,
  AdminUpdateBundleResponse,
  AdminToggleBundleResponse,
} from "../src/types/contracts.js";

export function mount(container: HTMLElement, bridge: AdminBridge): void {
  // ─── State ─────────────────────────────────────────────────────────────────
  let currentView: "list" | "create" | "edit" = "list";
  let currentBundleId: BundleId | null = null;
  let listPage = 1;
  const LIST_PAGE_SIZE = 20;
  let listStatusFilter = "all";

  // ─── CSS ───────────────────────────────────────────────────────────────────
  const style = document.createElement("style");
  style.textContent = `
    .bundles-app { font-family: var(--p-font-family-sans); }
    .bundles-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
    .bundles-table { width: 100%; border-collapse: collapse; }
    .bundles-table th, .bundles-table td { padding: 10px 12px; text-align: left; border-bottom: 1px solid var(--p-color-border); }
    .bundles-table th { font-weight: 600; color: var(--p-color-text-subdued); }
    .bundles-pagination { display: flex; gap: 8px; align-items: center; margin-top: 16px; justify-content: flex-end; }
    .form-field { margin-bottom: 16px; }
    .form-field label { display: block; font-weight: 600; margin-bottom: 4px; }
    .form-field input, .form-field select { width: 100%; padding: 8px; border: 1px solid var(--p-color-border); border-radius: 4px; }
    .tier-row { display: grid; grid-template-columns: 1fr 1fr 1fr 40px; gap: 8px; align-items: end; margin-bottom: 8px; }
    .member-row { display: flex; align-items: center; justify-content: space-between; padding: 8px; border: 1px solid var(--p-color-border); border-radius: 4px; margin-bottom: 8px; }
    .section-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
    .unavailable-badge { color: var(--p-color-text-critical); font-size: 12px; }
    .errors-list { color: var(--p-color-text-critical); margin-bottom: 12px; }
    .back-link { cursor: pointer; color: #008060; background: none; border: none; font-size: 14px; padding: 0; margin-bottom: 16px; display: inline-block; }
  `;
  container.appendChild(style);

  const app = document.createElement("div");
  app.className = "bundles-app";
  container.appendChild(app);

  // ─── Render dispatcher ─────────────────────────────────────────────────────
  function render(): void {
    if (currentView === "list") renderList();
    else if (currentView === "create") renderForm(null);
    else if (currentView === "edit" && currentBundleId) renderForm(currentBundleId);
  }

  // ─── List view ─────────────────────────────────────────────────────────────
  async function renderList(): Promise<void> {
    app.innerHTML = "";

    const header = document.createElement("div");
    header.className = "bundles-header shell-section";
    header.innerHTML = `
      <h2 style="margin:0;font-size:20px;">Product Bundles</h2>
      <div style="display:flex;gap:8px;align-items:center;">
        <select id="status-filter">
          <option value="all"${listStatusFilter === "all" ? " selected" : ""}>All</option>
          <option value="enabled"${listStatusFilter === "enabled" ? " selected" : ""}>Enabled</option>
          <option value="disabled"${listStatusFilter === "disabled" ? " selected" : ""}>Disabled</option>
        </select>
        <button class="btn-primary" id="create-btn">+ Create Bundle</button>
      </div>
    `;
    app.appendChild(header);

    header.querySelector<HTMLSelectElement>("#status-filter")!.addEventListener("change", (e) => {
      listStatusFilter = (e.target as HTMLSelectElement).value;
      listPage = 1;
      renderList();
    });
    header.querySelector("#create-btn")!.addEventListener("click", () => {
      currentView = "create";
      render();
    });

    const loadingEl = document.createElement("p");
    loadingEl.textContent = "Loading...";
    app.appendChild(loadingEl);

    let data: AdminListBundlesResponse;
    try {
      data = (await bridge.call("/admin/bundles", {
        page: listPage,
        page_size: LIST_PAGE_SIZE,
        status_filter: listStatusFilter,
      })) as AdminListBundlesResponse;
    } catch {
      loadingEl.remove();
      const err = document.createElement("div");
      err.className = "shell-error-banner";
      err.textContent = "Failed to load bundles. Please refresh.";
      app.appendChild(err);
      return;
    }

    loadingEl.remove();

    const card = document.createElement("div");
    card.className = "shell-card";

    if (data.items.length === 0) {
      card.innerHTML = `<p style="color:var(--p-color-text-subdued);text-align:center;padding:32px;">No bundles yet. Create your first bundle!</p>`;
    } else {
      const table = document.createElement("table");
      table.className = "bundles-table";
      table.innerHTML = `
        <thead>
          <tr>
            <th>Title</th>
            <th>Type</th>
            <th>Discount</th>
            <th>Status</th>
            <th>Purchases</th>
            <th>Created</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody id="bundles-tbody"></tbody>
      `;
      const tbody = table.querySelector<HTMLTableSectionElement>("#bundles-tbody")!;

      for (const bundle of data.items) {
        const tr = document.createElement("tr");
        const statusBadge = bundle.enabled
          ? `<span class="badge badge-success">Enabled</span>`
          : `<span class="badge">Disabled</span>`;
        const createdDate = new Intl.DateTimeFormat(bridge.context.locale, {
          dateStyle: "medium",
        }).format(new Date(bundle.created_at));
        tr.innerHTML = `
          <td><strong>${escHtml(bundle.title)}</strong></td>
          <td>${bundle.bundle_type}</td>
          <td>${bundle.discount_kind}</td>
          <td>${statusBadge}</td>
          <td>${bundle.purchase_count}</td>
          <td>${createdDate}</td>
          <td>
            <button class="btn-secondary edit-btn" data-id="${bundle.id}">Edit</button>
            <button class="${bundle.enabled ? "btn-destructive" : "btn-primary"} toggle-btn" data-id="${bundle.id}" data-enabled="${bundle.enabled}">
              ${bundle.enabled ? "Disable" : "Enable"}
            </button>
          </td>
        `;
        tbody.appendChild(tr);
      }

      table.querySelectorAll<HTMLButtonElement>(".edit-btn").forEach((btn) => {
        btn.addEventListener("click", () => {
          currentBundleId = btn.dataset["id"] as BundleId;
          currentView = "edit";
          render();
        });
      });

      table.querySelectorAll<HTMLButtonElement>(".toggle-btn").forEach((btn) => {
        btn.addEventListener("click", async () => {
          const bundleId = btn.dataset["id"] as BundleId;
          const currentEnabled = btn.dataset["enabled"] === "true";
          btn.disabled = true;
          try {
            await bridge.call("/admin/bundles/toggle", {
              bundle_id: bundleId,
              enabled: !currentEnabled,
            });
            bridge.notify(`Bundle ${!currentEnabled ? "enabled" : "disabled"}`, "success");
            renderList();
          } catch {
            bridge.notify("Failed to toggle bundle", "error");
            btn.disabled = false;
          }
        });
      });

      card.appendChild(table);
    }

    app.appendChild(card);

    // Pagination
    const totalPages = Math.ceil(data.total / data.page_size);
    if (totalPages > 1) {
      const pagination = document.createElement("div");
      pagination.className = "bundles-pagination";
      pagination.innerHTML = `
        <span style="color:var(--p-color-text-subdued);">Page ${data.page} of ${totalPages} (${data.total} total)</span>
        <button class="btn-secondary" id="prev-btn" ${data.page <= 1 ? "disabled" : ""}>← Prev</button>
        <button class="btn-secondary" id="next-btn" ${data.page >= totalPages ? "disabled" : ""}>Next →</button>
      `;
      pagination.querySelector("#prev-btn")!.addEventListener("click", () => {
        if (listPage > 1) { listPage--; renderList(); }
      });
      pagination.querySelector("#next-btn")!.addEventListener("click", () => {
        if (listPage < totalPages) { listPage++; renderList(); }
      });
      app.appendChild(pagination);
    }
  }

  // ─── Create / Edit form ───────────────────────────────────────────────────
  async function renderForm(bundleId: BundleId | null): Promise<void> {
    app.innerHTML = "";

    const isEdit = bundleId !== null;
    let existingDetail: AdminBundleDetailResponse | null = null;
    let members: MemberInput[] = [];
    let tiers: TierInput[] = isEdit ? [] : [{ min_item_count: 2, discount_value: "0.10", position: 0 }];
    let discountKind: DiscountKind = "percentage";
    let bundleType: BundleType = "fixed";
    let requiredCount = 3;
    let titleValue = "";
    let enabledValue = true;

    if (isEdit) {
      const loading = document.createElement("p");
      loading.textContent = "Loading bundle...";
      app.appendChild(loading);
      try {
        existingDetail = (await bridge.call("/admin/bundles/detail", {
          bundle_id: bundleId,
        })) as AdminBundleDetailResponse;
        loading.remove();
        titleValue = existingDetail.bundle.title;
        discountKind = existingDetail.bundle.discount_kind;
        bundleType = existingDetail.bundle.bundle_type;
        requiredCount = existingDetail.bundle.required_selection_count;
        enabledValue = existingDetail.bundle.enabled;
        members = existingDetail.members.map((m) => ({
          product_external_id: m.product_external_id,
          variant_external_id: m.variant_external_id,
          position: m.position,
        }));
        tiers = existingDetail.tiers.map((t) => ({
          min_item_count: t.min_item_count,
          discount_value: t.discount_value,
          discount_amount: t.discount_amount != null ? parseInt(t.discount_amount, 10) : null,
          discount_currency: t.discount_currency,
          free_item_count: t.free_item_count,
          position: t.position,
        }));
      } catch {
        loading.remove();
        const err = document.createElement("div");
        err.className = "shell-error-banner";
        err.textContent = "Failed to load bundle details.";
        app.appendChild(err);
        return;
      }
    }

    // Back button
    const backBtn = document.createElement("button");
    backBtn.className = "back-link";
    backBtn.textContent = "← Back to bundles";
    backBtn.addEventListener("click", () => {
      bridge.saveBar.hide();
      currentView = "list";
      render();
    });
    app.appendChild(backBtn);

    // Form card
    const card = document.createElement("div");
    card.className = "shell-card";

    const title = document.createElement("h2");
    title.textContent = isEdit ? "Edit Bundle" : "Create Bundle";
    title.style.marginTop = "0";
    card.appendChild(title);

    // Error container
    const errorsEl = document.createElement("div");
    errorsEl.className = "errors-list";
    errorsEl.style.display = "none";
    card.appendChild(errorsEl);

    // Title field
    const titleField = createField("Bundle Title", "text", titleValue, "Enter bundle title");
    card.appendChild(titleField.wrap);
    titleField.input.addEventListener("input", () => bridge.saveBar.show());

    // Bundle type
    const typeWrap = document.createElement("div");
    typeWrap.className = "form-field";
    typeWrap.innerHTML = `<label>Bundle Type</label>`;
    const typeSelect = document.createElement("select");
    typeSelect.innerHTML = `<option value="fixed">Fixed (all items required)</option><option value="flexible">Flexible (customer picks)</option>`;
    typeSelect.value = bundleType;
    typeSelect.addEventListener("change", () => {
      bundleType = typeSelect.value as BundleType;
      requiredCountWrap.style.display = bundleType === "flexible" ? "" : "none";
      bridge.saveBar.show();
    });
    typeWrap.appendChild(typeSelect);
    card.appendChild(typeWrap);

    // Required count (flexible only)
    const requiredCountField = createField("Required Items Count", "number", String(requiredCount), "e.g. 3");
    const requiredCountWrap = requiredCountField.wrap;
    requiredCountWrap.style.display = bundleType === "flexible" ? "" : "none";
    requiredCountField.input.min = "1";
    requiredCountField.input.addEventListener("input", () => bridge.saveBar.show());
    card.appendChild(requiredCountWrap);

    // Discount kind
    const discountKindWrap = document.createElement("div");
    discountKindWrap.className = "form-field";
    discountKindWrap.innerHTML = `<label>Discount Type</label>`;
    const discountKindSelect = document.createElement("select");
    discountKindSelect.innerHTML = `
      <option value="percentage">Percentage off</option>
      <option value="flat_amount">Flat amount off</option>
      <option value="bxgy">Buy X Get Y Free</option>
    `;
    discountKindSelect.value = discountKind;
    discountKindSelect.addEventListener("change", () => {
      discountKind = discountKindSelect.value as DiscountKind;
      renderTiers();
      bridge.saveBar.show();
    });
    discountKindWrap.appendChild(discountKindSelect);
    card.appendChild(discountKindWrap);

    // Enabled toggle
    const enabledWrap = document.createElement("div");
    enabledWrap.className = "form-field";
    const enabledLabel = document.createElement("label");
    const enabledCheckbox = document.createElement("input");
    enabledCheckbox.type = "checkbox";
    enabledCheckbox.checked = enabledValue;
    enabledCheckbox.addEventListener("change", () => bridge.saveBar.show());
    enabledLabel.appendChild(enabledCheckbox);
    enabledLabel.appendChild(document.createTextNode(" Bundle enabled"));
    enabledWrap.appendChild(enabledLabel);
    card.appendChild(enabledWrap);

    // ─── Members section ─────────────────────────────────────────────────
    const membersSection = document.createElement("div");
    membersSection.className = "shell-section";
    const membersHeader = document.createElement("div");
    membersHeader.className = "section-header";
    membersHeader.innerHTML = `<strong>Bundle Members</strong>`;
    const addMemberBtn = document.createElement("button");
    addMemberBtn.className = "btn-secondary";
    addMemberBtn.textContent = "+ Add Product/Variant";
    addMemberBtn.addEventListener("click", async () => {
      const picked = await bridge.pickResource({ type: "variant" });
      if (!picked || picked.length === 0) return;
      for (const resource of picked) {
        // GID format: gid://shopify/ProductVariant/123456
        const variantGidParts = resource.id.split("/");
        const variantId = variantGidParts[variantGidParts.length - 1] ?? "";
        members.push({
          product_external_id: variantId, // we'll use variantId as product ref for now
          variant_external_id: variantId,
          position: members.length,
        });
        bridge.saveBar.show();
        renderMembers();
      }
    });
    membersHeader.appendChild(addMemberBtn);
    membersSection.appendChild(membersHeader);

    const membersContainer = document.createElement("div");
    membersSection.appendChild(membersContainer);
    card.appendChild(membersSection);

    function renderMembers(): void {
      membersContainer.innerHTML = "";
      if (members.length === 0) {
        const empty = document.createElement("p");
        empty.style.color = "var(--p-color-text-subdued)";
        empty.textContent = "No members added yet.";
        membersContainer.appendChild(empty);
        return;
      }
      members.forEach((m, idx) => {
        const memberRow = document.createElement("div");
        memberRow.className = "member-row";

        const info = document.createElement("span");
        const unavailableNote = isEdit && existingDetail?.members[idx]
          ? (!existingDetail.members[idx]!.available ? " ⚠ Unavailable" : "")
          : "";
        info.textContent = m.variant_external_id
          ? `Variant ID: ${m.variant_external_id}${unavailableNote}`
          : `Product ID: ${m.product_external_id}${unavailableNote}`;
        if (unavailableNote) info.className = "unavailable-badge";

        const removeBtn = document.createElement("button");
        removeBtn.className = "btn-destructive";
        removeBtn.textContent = "Remove";
        removeBtn.addEventListener("click", () => {
          members.splice(idx, 1);
          members.forEach((mem, i) => { mem.position = i; });
          bridge.saveBar.show();
          renderMembers();
        });

        memberRow.appendChild(info);
        memberRow.appendChild(removeBtn);
        membersContainer.appendChild(memberRow);
      });
    }

    renderMembers();

    // ─── Tiers section ─────────────────────────────────────────────────────
    const tiersSection = document.createElement("div");
    tiersSection.className = "shell-section";
    const tiersHeader = document.createElement("div");
    tiersHeader.className = "section-header";
    tiersHeader.innerHTML = `<strong>Discount Tiers</strong><small style="color:var(--p-color-text-subdued)">More items = bigger discount</small>`;
    const addTierBtn = document.createElement("button");
    addTierBtn.className = "btn-secondary";
    addTierBtn.textContent = "+ Add Tier";
    addTierBtn.addEventListener("click", () => {
      const lastTier = tiers[tiers.length - 1];
      tiers.push({
        min_item_count: lastTier ? lastTier.min_item_count + 1 : 2,
        discount_value: "0.10",
        position: tiers.length,
      });
      bridge.saveBar.show();
      renderTiers();
    });
    tiersHeader.appendChild(addTierBtn);
    tiersSection.appendChild(tiersHeader);

    const tiersContainer = document.createElement("div");
    tiersSection.appendChild(tiersContainer);
    card.appendChild(tiersSection);

    function renderTiers(): void {
      tiersContainer.innerHTML = "";

      // Column headers
      const headerRow = document.createElement("div");
      headerRow.className = "tier-row";
      headerRow.innerHTML = `<strong>Min Items</strong>`;
      if (discountKind === "percentage") {
        headerRow.innerHTML += `<strong>% Off (0-100)</strong>`;
      } else if (discountKind === "flat_amount") {
        headerRow.innerHTML += `<strong>Amount Off (${bridge.context.currency})</strong>`;
      } else {
        headerRow.innerHTML += `<strong>Free Items</strong>`;
      }
      headerRow.innerHTML += `<span></span><span></span>`;
      tiersContainer.appendChild(headerRow);

      tiers.forEach((tier, idx) => {
        const row = document.createElement("div");
        row.className = "tier-row";

        const minInput = document.createElement("input");
        minInput.type = "number";
        minInput.min = "1";
        minInput.value = String(tier.min_item_count);
        minInput.addEventListener("change", () => {
          tier.min_item_count = parseInt(minInput.value, 10) || 1;
          bridge.saveBar.show();
        });

        const valueInput = document.createElement("input");
        if (discountKind === "percentage") {
          valueInput.type = "number";
          valueInput.min = "0";
          valueInput.max = "100";
          valueInput.step = "0.1";
          const pctDisplay = tier.discount_value ? parseFloat(tier.discount_value) * 100 : 10;
          valueInput.value = String(pctDisplay);
          valueInput.addEventListener("change", () => {
            tier.discount_value = String(parseFloat(valueInput.value) / 100);
            bridge.saveBar.show();
          });
        } else if (discountKind === "flat_amount") {
          valueInput.type = "number";
          valueInput.min = "0";
          valueInput.step = "0.01";
          const majorAmount = tier.discount_amount != null
            ? tier.discount_amount / 100
            : 0;
          valueInput.value = String(majorAmount);
          valueInput.addEventListener("change", () => {
            tier.discount_amount = Math.round(parseFloat(valueInput.value) * 100);
            tier.discount_currency = bridge.context.currency;
            bridge.saveBar.show();
          });
        } else {
          // bxgy
          valueInput.type = "number";
          valueInput.min = "1";
          valueInput.value = String(tier.free_item_count ?? 1);
          valueInput.addEventListener("change", () => {
            tier.free_item_count = parseInt(valueInput.value, 10) || 1;
            bridge.saveBar.show();
          });
        }

        const emptyCol = document.createElement("span");

        const removeBtn = document.createElement("button");
        removeBtn.className = "btn-destructive";
        removeBtn.textContent = "✕";
        removeBtn.addEventListener("click", () => {
          tiers.splice(idx, 1);
          tiers.forEach((t, i) => { t.position = i; });
          bridge.saveBar.show();
          renderTiers();
        });

        row.appendChild(minInput);
        row.appendChild(valueInput);
        row.appendChild(emptyCol);
        row.appendChild(removeBtn);
        tiersContainer.appendChild(row);
      });
    }

    renderTiers();

    // ─── Purchase count (edit only) ────────────────────────────────────────
    if (isEdit && existingDetail) {
      const purchaseInfo = document.createElement("p");
      purchaseInfo.style.color = "var(--p-color-text-subdued)";
      purchaseInfo.textContent = `Total purchases: ${existingDetail.purchase_count}`;
      card.appendChild(purchaseInfo);
    }

    // ─── Submit button ─────────────────────────────────────────────────────
    const submitBtn = document.createElement("button");
    submitBtn.className = "btn-primary";
    submitBtn.textContent = isEdit ? "Save Changes" : "Create Bundle";
    submitBtn.style.marginTop = "16px";

    submitBtn.addEventListener("click", async () => {
      errorsEl.style.display = "none";
      errorsEl.innerHTML = "";

      const newTitle = (titleField.input as HTMLInputElement).value.trim();
      const newEnabled = enabledCheckbox.checked;
      const newRequiredCount = parseInt((requiredCountField.input as HTMLInputElement).value, 10) || 0;

      const validationErrors: string[] = [];
      if (!newTitle) validationErrors.push("Title is required");
      if (members.length === 0) validationErrors.push("At least one member is required");
      if (tiers.length === 0) validationErrors.push("At least one tier is required");
      if (bundleType === "flexible" && newRequiredCount < 1) validationErrors.push("Required count must be ≥ 1 for flexible bundles");

      if (validationErrors.length > 0) {
        showErrors(validationErrors);
        return;
      }

      submitBtn.disabled = true;
      submitBtn.textContent = isEdit ? "Saving..." : "Creating...";

      try {
        if (isEdit && bundleId) {
          const resp = (await bridge.call("/admin/bundles/update", {
            bundle_id: bundleId,
            title: newTitle,
            discount_kind: discountKind,
            required_selection_count: newRequiredCount,
            members,
            tiers,
            enabled: newEnabled,
          })) as AdminUpdateBundleResponse;

          if (resp.errors && resp.errors.length > 0) {
            showErrors(resp.errors);
          } else {
            bridge.notify("Bundle updated successfully", "success");
            bridge.saveBar.hide();
            currentView = "list";
            render();
          }
        } else {
          const resp = (await bridge.call("/admin/bundles/create", {
            title: newTitle,
            bundle_type: bundleType,
            discount_kind: discountKind,
            required_selection_count: newRequiredCount,
            members,
            tiers,
            enabled: newEnabled,
          })) as AdminCreateBundleResponse;

          if (resp.errors && resp.errors.length > 0) {
            showErrors(resp.errors);
          } else {
            bridge.notify("Bundle created successfully", "success");
            bridge.saveBar.hide();
            currentView = "list";
            render();
          }
        }
      } catch {
        bridge.notify("An unexpected error occurred", "error");
      } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = isEdit ? "Save Changes" : "Create Bundle";
      }
    });

    card.appendChild(submitBtn);
    app.appendChild(card);

    function showErrors(errs: string[]): void {
      errorsEl.innerHTML = "";
      const ul = document.createElement("ul");
      for (const e of errs) {
        const li = document.createElement("li");
        li.textContent = e;
        ul.appendChild(li);
      }
      errorsEl.appendChild(ul);
      errorsEl.style.display = "";
    }
  }

  // ─── Helpers ───────────────────────────────────────────────────────────────
  function createField(
    labelText: string,
    inputType: string,
    value: string,
    placeholder: string
  ): { wrap: HTMLDivElement; input: HTMLInputElement } {
    const wrap = document.createElement("div");
    wrap.className = "form-field";
    const label = document.createElement("label");
    label.textContent = labelText;
    const input = document.createElement("input");
    input.type = inputType;
    input.value = value;
    input.placeholder = placeholder;
    wrap.appendChild(label);
    wrap.appendChild(input);
    return { wrap, input };
  }

  function escHtml(str: string): string {
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  // ─── Initial render ────────────────────────────────────────────────────────
  render();
}
